+  await started(page);
+  await page.keyboard.down("ArrowDown");
+  await expect
+    .poll(async () => (await state(page)).player.pitch)
+    .toBeLessThan(-0.2);
+  await expect
+    .poll(async () => (await state(page)).player.position.y)
